/* CBS Scope of works page (job menu, Plan): cbs-scope?job=N. Data from cbs-scope-data, changes to cbs-scope-act.
   Two views of the same scope: by section (areas on project jobs, phases on CDM jobs) and by package (who is doing it). */
const S=v=>v==null?'':String(v);const e=t=>S(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const q=$input.first().json.query||{};const job=S(q.job).replace(/[^0-9A-Za-z-]/g,'');
const D={job:job};
const CSS='*{box-sizing:border-box}body{margin:0;background:#f2f2f0;color:#161616;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;font-size:16px;line-height:1.4}'
+'header{background:#3d4043;color:#fff;padding:12px 16px;border-bottom:4px solid #F47920;position:sticky;top:0;z-index:5}header .nav{display:flex;flex-wrap:wrap;gap:6px 14px}header a.hub{color:#ffb37a;font-size:13px;text-decoration:none}header h1{margin:4px 0 0;font-size:20px}header p{margin:3px 0 0;color:#ccc;font-size:13px}'
+'.wrap{max-width:980px;margin:0 auto;padding:14px}'
+'.btn{background:#F47920;color:#fff;text-decoration:none;font-weight:600;border-radius:8px;padding:9px 14px;font-size:14px;border:0;font-family:inherit;cursor:pointer;min-height:40px}.btn.ghost{background:#fff;color:#1d1d1d;border:1px solid #c9cbcd}.btn.sm{padding:6px 10px;font-size:13px;min-height:34px}.btn:disabled{opacity:.5;cursor:default}.btn.red{background:#fff;color:#b3261e;border:1px solid #e9b6b1}'
+'.top{background:#fff;border:1px solid #d9d9d6;border-radius:12px;padding:12px 14px;margin-bottom:10px;display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between}'
+'.chip{display:inline-block;font-size:12px;font-weight:600;border-radius:20px;padding:2px 9px;background:#eee;color:#333;margin-right:6px}.chip.cdm{background:#3d4043;color:#fff}.chip.Approved{background:#e3f4e6;color:#1d6b2c}.chip.Completed{background:#e9e9e7;color:#555}.chip.Estimate{background:#e6efff;color:#1f5fbf}'
+'.seg{display:inline-flex;border:1px solid #c9cbcd;border-radius:8px;overflow:hidden}.seg button{font:inherit;font-size:14px;border:0;background:#fff;padding:8px 14px;cursor:pointer;min-height:40px}.seg button.on{background:#3d4043;color:#fff;font-weight:600}'
+'.lock{background:#fff8ea;border:1px solid #f2d398;border-radius:12px;padding:10px 14px;margin-bottom:10px;display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between}.lock b{color:#7a4a00}.lock span{color:#5c3a10;font-size:14px}'
+'.tools{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px;align-items:center}.tools .sp{flex:1}.cnt{color:#555;font-size:14px}'
+'.srch{width:100%;font:inherit;padding:10px 12px;border:1px solid #ccc;border-radius:10px;margin-bottom:10px}'
+'.sec{background:#fff;border:1px solid #d9d9d6;border-radius:12px;margin-bottom:10px;overflow:hidden}.sh{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center;justify-content:space-between;padding:10px 14px;background:#fafaf8;border-bottom:1px solid #eee}'
+'.sh .n{font-weight:700;color:#6b6e70;margin-right:6px}.sh .t{font-weight:600;font-size:16px}.sh .m{color:#555;font-size:13px}.sh .acts{display:flex;gap:6px;flex-wrap:wrap}'
+'.it{display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:10px;align-items:start;padding:10px 14px;border-bottom:1px solid #f0f0ee;cursor:pointer}.it:hover{background:#fbfaf7}.it:last-child{border-bottom:0}'
+'.it .r{color:#6b6e70;font-variant-numeric:tabular-nums;padding-top:2px}.it .x{min-width:0}.it .tx{white-space:pre-wrap}.it .nt{font-size:13px;color:#555;margin-top:3px;white-space:pre-wrap}.it .sr{font-size:12px;color:#6b6e70;margin-top:3px}'
+'.who{display:inline-block;font-size:12px;font-weight:600;border-radius:20px;padding:2px 9px;white-space:nowrap}.who.cbs{background:#F47920;color:#fff}.who.sub{border:1px solid #F47920;color:#8a3f07;background:#fff}.who.none{border:1px dashed #8a8d90;color:#4a4d50}'
+'.vtag{display:inline-block;font-size:11.5px;font-weight:700;border-radius:20px;padding:1px 7px;border:1px solid #b45309;color:#8a3f07;margin-left:6px;vertical-align:1px}.ptag{font-size:12px;color:#1d6b2c;font-weight:600}'
+'.addrow{padding:8px 14px}.addrow button{font:inherit;font-size:14px;color:#8a3f07;background:none;border:0;cursor:pointer;padding:6px 0}'
+'.phase{display:inline-block;font-size:12px;background:#f0f0ee;color:#3d4043;border-radius:6px;padding:2px 8px;white-space:nowrap}'
+'.empty{color:#6b6e70;padding:18px 14px;text-align:center;background:#fff;border:1px dashed #d9d9d6;border-radius:12px}'
+'.start{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}@media(max-width:700px){.start{grid-template-columns:1fr}}.st{background:#fff;border:1px solid #d9d9d6;border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:8px}.st b{font-size:15px}.st p{margin:0;color:#555;font-size:14px;flex:1}.st.off{background:#fafaf8}.st.off b{color:#6b6e70}'
+'.ov{position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:20;display:flex;align-items:flex-start;justify-content:center;padding:20px 10px;overflow:hidden}.dlg{background:#fff;border-radius:14px;max-width:560px;width:100%;padding:16px;max-height:calc(100vh - 40px);overflow-y:auto}.dlg h2{margin:0 0 10px;font-size:18px}'
+'.dw{position:fixed;top:0;right:0;bottom:0;width:min(480px,100%);background:#fff;z-index:21;display:flex;flex-direction:column;box-shadow:-4px 0 18px rgba(0,0,0,.2)}.dwbg{position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:20}.dw .dh{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:14px 16px;border-bottom:1px solid #eee}.dw .dh h2{margin:0;font-size:17px}.dw .db{flex:1;min-height:0;overflow-y:auto;padding:14px 16px}.dw .df{display:flex;justify-content:space-between;gap:8px;padding:12px 16px;border-top:1px solid #eee}'
+'label.f{display:block;font-size:13px;font-weight:600;color:#444;margin:12px 0 4px}.dlg input[type=text],.dlg select,.dlg textarea,.dw input[type=text],.dw input[type=email],.dw select,.dw textarea{width:100%;font:inherit;padding:10px;border:1px solid #c4c6c8;border-radius:8px;background:#fff}textarea{min-height:80px;resize:vertical}'
+'.note{font-size:13px;color:#6b6e70;margin-top:6px}.msg{font-size:14px;color:#8a5a00;margin-top:8px;min-height:18px}.b{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}'
+'.lk{background:#f4f4f2;border-radius:10px;padding:10px 12px;margin-top:14px;font-size:14px}.lk div{display:flex;justify-content:space-between;gap:8px;padding:2px 0}.lk span{color:#555}'
+'.chk{display:flex;gap:10px;align-items:flex-start;padding:7px 0;border-top:1px solid #eee}.chk input{width:20px;height:20px;flex:0 0 auto}.chk.in{padding-left:28px}'
+'.hist{white-space:pre-wrap;font-size:12px;color:#6b6e70;margin-top:8px}';
const nav='<div class="nav"><a class="hub" href="/webhook/cbs-admin">&larr; Operations Hub</a>'+(job?'<a class="hub" href="/webhook/cbs-job-file?job='+encodeURIComponent(job)+'">Job</a>':'')+'</div>';
const html='<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scope of works - Job '+e(job)+'</title><script src="/webhook/cbs-guard"></script><style>'+CSS+'</style><script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script></head><body><header>'+nav+'<h1>Scope of works'+(job?' \u00b7 Job '+e(job):'')+'</h1><p>Chelmsford Building Services</p></header><div class="wrap" id="app">'+(job?'<div class="empty">Loading\u2026</div>':'<div class="empty">Open the scope of works from a job.</div>')+'</div><script>window.D='+JSON.stringify(D).replace(/</g,'\\u003c')+';</script>'+(job?'<script>('+client.toString()+')();</script>':'')+'</body></html>';
return [{json:{html:html}}];

function client(){
var D=window.D,JOB=D.job,app=document.getElementById('app'),DATA=null,VIEW='sec',Q='',BUSY=false,LOGO=null;
try{VIEW=localStorage.getItem('cbsScopeView')||'sec';}catch(z){}
function s(v){return v==null?'':String(v);}
function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function dmy(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:s(d);}
function me(){var x='';try{var m=JSON.parse(localStorage.getItem('cbs_me')||'null');if(m&&m.name)x=m.name;}catch(z){}if(!x){try{x=localStorage.getItem('cbs_name')||'';}catch(z){}}return x;}
function lockScroll(on){document.documentElement.style.overflow=on?'hidden':'';document.body.style.overflow=on?'hidden':'';}
function dlg(html){var o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg" role="dialog">'+html+'</div>';document.body.appendChild(o);lockScroll(true);o.close=function(){o.remove();if(!document.querySelector('.ov,.dw'))lockScroll(false);};o.addEventListener('click',function(ev){if(ev.target===o&&!o.noBg)o.close();});return o;}
function ask(title,text,okLabel,danger){return new Promise(function(res){var o=dlg('<h2>'+e(title)+'</h2><div style="white-space:pre-wrap">'+e(text)+'</div><div class="b"><button class="btn'+(danger?' red':'')+'" id="aok">'+e(okLabel||'OK')+'</button><button class="btn ghost" id="ax">Cancel</button></div>');
 o.querySelector('#aok').onclick=function(){o.close();res(true);};o.querySelector('#ax').onclick=function(){o.close();res(false);};o.addEventListener('click',function(ev){if(ev.target===o)res(false);});});}
function tell(title,text){var o=dlg('<h2>'+e(title)+'</h2><div style="white-space:pre-wrap">'+e(text)+'</div><div class="b"><button class="btn" id="aok">OK</button></div>');o.querySelector('#aok').onclick=o.close;}
function who(){var x=me();if(x)return Promise.resolve(x);return new Promise(function(res){var o=dlg('<h2>Your name</h2><div class="note">So the history shows who made the change.</div><input type="text" id="nm" autocomplete="name"><div class="b"><button class="btn" id="nok">Continue</button><button class="btn ghost" id="nx">Cancel</button></div>');
 var i=o.querySelector('#nm');i.focus();o.querySelector('#nok').onclick=function(){var v=i.value.trim();if(!v){i.focus();return;}try{localStorage.setItem('cbs_name',v);}catch(z){}o.close();res(v);};o.querySelector('#nx').onclick=function(){o.close();res('');};});}
function post(body){if(BUSY)return Promise.resolve({ok:false,busy:true});return who().then(function(by){if(!by)return {ok:false,cancel:true};BUSY=true;body.job=JOB;body.by=by;
 return fetch('/webhook/cbs-scope-act',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){if(!r.ok)throw 0;return r.json();}).catch(function(){return {ok:false,message:'Could not save. Check your connection and try again.'};}).then(function(x){BUSY=false;if(x&&x.ok&&x.scope&&DATA){DATA.scope=x.scope;render();}return x;});});}
function load(){return fetch('/webhook/cbs-scope-data?job='+encodeURIComponent(JOB),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){if(!d||!d.ok)throw 0;DATA=d;var hp=document.querySelector('header p');if(hp)hp.textContent=[d.site,d.client].filter(Boolean).join(' \u00b7 ')||'Chelmsford Building Services';render();}).catch(function(){app.innerHTML='<div class="empty">Could not load the scope. Refresh to try again.</div>';});}
function secs(){return (DATA&&DATA.scope&&DATA.scope.sections)||[];}
function subs(){return (DATA&&DATA.subs)||[];}
function whoCls(w){w=s(w);if(!w)return 'none';return w==='CBS'?'cbs':'sub';}
function whoLab(w){w=s(w);return w==='CBS'?'CBS (own crew)':(w||'Not assigned');}
function progName(id){var p=((DATA.prog&&DATA.prog.phases)||[]).filter(function(x){return x.id===s(id);})[0];return p?p.name:'';}
function inProg(id){return !!id&&((DATA.prog&&DATA.prog.ids)||[]).indexOf(s(id))>-1;}
function match(i,sc){var q=Q.toLowerCase();if(!q)return true;return [i.text,i.notes,i.who,i.var,sc.name].join(' ').toLowerCase().indexOf(q)>-1;}
function nItems(){return secs().reduce(function(m,x){return m+(x.items||[]).length;},0);}
function render(){
 var d=DATA,h='',L=d.locked;
 h+='<div class="top"><div><span class="chip '+e(d.stage)+'">'+e(d.stage)+'</span><span class="chip'+(d.cdm?' cdm':'')+'">'+(d.cdm?'CDM':'Project')+'</span><span class="cnt">'+secs().length+' section'+(secs().length===1?'':'s')+' \u00b7 '+nItems()+' item'+(nItems()===1?'':'s')+'</span></div>'
  +'<div class="seg" role="group" aria-label="Scope view"><button data-v="sec" class="'+(VIEW==='sec'?'on':'')+'">By section</button><button data-v="pkg" class="'+(VIEW==='pkg'?'on':'')+'">By package</button></div></div>';
 if(L)h+='<div class="lock"><div><b>Scope locked at Approved.</b> <span>What is being done changes through Variations. Who and crew notes can still be changed.</span></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="btn ghost sm" href="/webhook/cbs-variations?job='+encodeURIComponent(JOB)+'">Variations</a>'+((d.vars||[]).length?'<button class="btn sm" id="addVar">+ Add from variation</button>':'')+'</div></div>';
 if(!secs().length){h+=startHtml();app.innerHTML=h;wire();return;}
 h+='<div class="tools">'+(!L?'<button class="btn" id="addSec">+ Add section</button>':'')+'<button class="btn ghost" id="bProg">'+(secs().some(function(x){return inProg(x.prog_id);})?'Update programme from scope':'Build programme from scope')+'</button><button class="btn ghost" id="pdf">Download PDF</button><span class="sp"></span><a class="btn ghost sm" href="/webhook/cbs-scope-crew?job='+encodeURIComponent(JOB)+'" target="_blank" rel="noopener" data-noview>Crew view</a></div>';
 h+='<input class="srch" id="q" placeholder="Search the scope" value="'+e(Q)+'">';
 h+=VIEW==='pkg'?pkgHtml():secHtml();
 if(d.history)h+='<details style="margin-top:6px"><summary class="note" style="cursor:pointer">History</summary><div class="hist">'+e(d.history)+'</div></details>';
 app.innerHTML=h;wire();}
function startHtml(){var d=DATA,sv=d.surveys||[],h='<div class="sec" style="padding:16px"><div style="font-size:18px;font-weight:600">No scope yet</div><div class="note" style="margin-top:4px">Pick how to start. The scope stays a draft at Estimate and locks when the job is Approved.</div></div>';
 if(d.locked)return h+'<div class="empty">The job is already Approved, so a scope can only be added through a variation. Move the job back to Estimate to write the scope from scratch.</div>';
 h+='<div class="start">';
 h+='<div class="st'+(sv.length?'':' off')+'"><b>Pull from site survey</b><p>Each survey area becomes a section, with its scope lines as items and the recommended work as crew notes.</p>'+(sv.length?'<button class="btn ghost" id="fromSv">'+(sv.length>1?'Choose survey ('+sv.length+')':'Use survey of '+e(dmy(sv[0].date)))+'</button>':'<button class="btn ghost" disabled>No survey on this job</button>')+'</div>';
 h+='<div class="st"><b>Start from job description</b><p>One section filled from the ServiceM8 job description. Quickest for reactive and small jobs.</p><button class="btn ghost" id="fromDesc">Use description</button></div>';
 h+='<div class="st"><b>Start blank</b><p>Type it in from the enquiry email, client spec or phone call.</p><button class="btn" id="addSec">+ Add section</button></div>';
 return h+'</div>';}
function secHtml(){var h='',L=DATA.locked,any=false;
 secs().forEach(function(sc,si){var items=(sc.items||[]).map(function(it,ii){return {it:it,ref:(si+1)+'.'+(ii+1)};}).filter(function(x){return match(x.it,sc);});
  if(Q&&!items.length)return;any=true;
  h+='<div class="sec" data-sid="'+e(sc.id)+'"><div class="sh"><div><span class="n">'+(si+1)+'</span><span class="t">'+e(sc.name)+'</span> <span class="m">\u00b7 default '+e(whoLab(sc.who))+'</span>'+(inProg(sc.prog_id)?' <span class="ptag">\u00b7 in programme</span>':'')+'</div>'
   +'<div class="acts"><button class="btn ghost sm" data-sa="edit">Edit</button><button class="btn ghost sm" data-sa="up" aria-label="Move up"'+(si?'':' disabled')+'>\u2191</button><button class="btn ghost sm" data-sa="down" aria-label="Move down"'+(si<secs().length-1?'':' disabled')+'>\u2193</button>'+(!L?'<button class="btn red sm" data-sa="del">Delete</button>':'')+'</div></div>';
  if(!items.length)h+='<div class="addrow note">No items yet.</div>';
  items.forEach(function(x){var it=x.it;h+='<div class="it" data-iid="'+e(it.id)+'" tabindex="0" role="button" aria-label="Edit item '+x.ref+'"><span class="r">'+x.ref+'</span><div class="x"><div class="tx">'+e(it.text)+(it.var?'<span class="vtag">'+e(it.var)+'</span>':'')+'</div>'+(it.notes?'<div class="nt">'+e(it.notes)+'</div>':'')+(it.src?'<div class="sr">'+e(it.src)+'</div>':'')+'</div><span class="who '+whoCls(it.who)+'">'+e(whoLab(it.who))+'</span></div>';});
  if(!L)h+='<div class="addrow"><button data-sa="additem">+ Add item</button></div>';
  h+='</div>';});
 if(!any)h+='<div class="empty">Nothing matches your search.</div>';return h;}
function groups(){var G={},order=[];secs().forEach(function(sc,si){(sc.items||[]).forEach(function(it,ii){if(!match(it,sc))return;var k=s(it.who)||'';if(!G[k]){G[k]=[];order.push(k);}G[k].push({it:it,ref:(si+1)+'.'+(ii+1),sec:sc,si:si});});});
 order.sort(function(a,b){if(!a)return -1;if(!b)return 1;if(a==='CBS')return -1;if(b==='CBS')return 1;return a.localeCompare(b);});return {G:G,order:order};}
function pkgHtml(){var g=groups(),h='';if(!g.order.length)return '<div class="empty">Nothing matches your search.</div>';
 g.order.forEach(function(k){var L=g.G[k],ph={};L.forEach(function(x){ph[x.si+1]=1;});var isSub=k&&k!=='CBS';var sb=subs().filter(function(x){return x.name===k;})[0];
  h+='<div class="sec" data-pk="'+e(k)+'"><div class="sh"><div><span class="who '+whoCls(k)+'">'+e(whoLab(k))+'</span> <span class="m">'+L.length+' item'+(L.length===1?'':'s')+' \u00b7 section'+(Object.keys(ph).length===1?' ':'s ')+Object.keys(ph).join(', ')+'</span></div><div class="acts">'
   +(!k?'<span class="note">Open an item to say who is doing it.</span>':'')
   +(isSub?'<button class="btn ghost sm" data-pa="rams">'+(sb&&sb.email?'Email RAMS request':'RAMS request (no email)')+'</button>':'')
   +(k==='CBS'?'<a class="btn ghost sm" href="/webhook/cbs-job-rams?job='+encodeURIComponent(JOB)+'">CBS RAMS</a>':'')
   +(k?'<button class="btn ghost sm" data-pa="pdf">Package PDF</button>':'')+'</div></div>';
  L.forEach(function(x){var it=x.it;h+='<div class="it" data-iid="'+e(it.id)+'" tabindex="0" role="button"><span class="r">'+x.ref+'</span><div class="x"><div class="tx">'+e(it.text)+(it.var?'<span class="vtag">'+e(it.var)+'</span>':'')+'</div>'+(it.notes?'<div class="nt">'+e(it.notes)+'</div>':'')+'</div><span class="phase">'+(x.si+1)+' \u00b7 '+e(x.sec.name)+'</span></div>';});
  h+='</div>';});return h;}
function wire(){
 app.querySelectorAll('[data-v]').forEach(function(b){b.onclick=function(){VIEW=b.getAttribute('data-v');try{localStorage.setItem('cbsScopeView',VIEW);}catch(z){}render();};});
 var qi=document.getElementById('q');if(qi)qi.oninput=function(){Q=qi.value;var p=qi.selectionStart;render();var x=document.getElementById('q');x.focus();try{x.setSelectionRange(p,p);}catch(z){}};
 var b;if((b=document.getElementById('addSec')))b.onclick=function(){secDlg(null);};
 if((b=document.getElementById('addVar')))b.onclick=function(){varDlg();};
 if((b=document.getElementById('fromSv')))b.onclick=surveyDlg;
 if((b=document.getElementById('fromDesc')))b.onclick=function(){var t=this;ask('Start from the job description','Fill one section from the ServiceM8 job description? You can edit everything afterwards.','Use description').then(function(ok){if(!ok)return;t.disabled=true;post({a:'seed',from:'desc'}).then(function(x){t.disabled=false;if(!x.ok&&!x.cancel&&!x.busy)tell('Could not start the scope',x.message||'Try again.');});});};
 if((b=document.getElementById('bProg')))b.onclick=buildProg;
 if((b=document.getElementById('pdf')))b.onclick=function(){pdfDlg('');};
 app.querySelectorAll('.sec[data-sid]').forEach(function(card){var sc=secs().filter(function(x){return x.id===card.getAttribute('data-sid');})[0];
  card.querySelectorAll('[data-sa]').forEach(function(btn){var a=btn.getAttribute('data-sa');btn.onclick=function(ev){ev.stopPropagation();
   if(a==='edit')secDlg(sc);else if(a==='additem')itemDw(null,sc);else if(a==='up'||a==='down'){btn.disabled=true;post({a:'move_section',sid:sc.id,dir:a});}
   else if(a==='del')ask('Delete section','Delete "'+sc.name+'" and its '+(sc.items||[]).length+' item'+((sc.items||[]).length===1?'':'s')+'?','Delete',true).then(function(ok){if(!ok)return;return ask('Are you sure?','This removes the section and everything in it from the scope.','Yes, delete it',true).then(function(ok2){if(ok2)post({a:'del_section',sid:sc.id});});});};});});
 app.querySelectorAll('.it[data-iid]').forEach(function(r){function go(){var f=find(r.getAttribute('data-iid'));if(f)itemDw(f.it,f.sc);}r.onclick=go;r.onkeydown=function(ev){if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();go();}};});
 app.querySelectorAll('.sec[data-pk]').forEach(function(card){var k=card.getAttribute('data-pk');card.querySelectorAll('[data-pa]').forEach(function(btn){btn.onclick=function(){var a=btn.getAttribute('data-pa');if(a==='pdf')pdfDlg(k);else if(a==='rams')ramsMail(k);};});});}
