const P=[list('scope'),list('jobrows'),get('cbs-sm8-job?no='+encodeURIComponent(job)),get('cbs-programme-data?job='+encodeURIComponent(job))];
if(!crew)P.push(list('subbies'),list('suppliers'),list('variations'),list('surveys'));
const R=await Promise.all(P);
const SC=R[0],J=R[1],SM=R[2]||{},PG=R[3]||{};
const row=SC.filter(r=>jk(r.job_no)===jk(job)).sort((a,b)=>num(b.id)-num(a.id))[0]||null;
let scope={v:1,next:1,sections:[]};try{const x=JSON.parse(S(row&&row.scope_json)||'null');if(x&&Array.isArray(x.sections))scope=x;}catch(e){}
