const sm8=SM&&SM.found?S(SM.status):'';
const hubSt=S(jr&&jr.status);
const live=sm8||hubSt;
const approved=/work ?order|approved|completed/i.test(live);
const locked=!!scope.locked_at; /* locks only when someone presses Lock scope */
const stage=/completed/i.test(live)?'Completed':(approved?'Approved':(/unsuccessful/i.test(live)?'Unsuccessful':'Estimate'));
const cdm=!!(jr&&(jr.cdm===true||String(jr.cdm)==='true'||/cdm/i.test(S(jr.mode))));
/* programme: phases with dates; which phase is now */
const phases=(Array.isArray(PG.phases)?PG.phases:[]).map(p=>({id:String(p.id),name:S(p.name),start:S(p.start_eff),end:S(p.end_eff),pct:num(p.pct),tasks:(p.tasks||[]).map(t=>String(t.id)).concat([].concat.apply([],(p.tasks||[]).map(t=>(t.subs||[]).map(s=>String(s.id)))))}));
let cur=phases.find(p=>p.start&&p.start<=today&&(p.end||p.start)>=today&&p.pct<100)||null;
if(!cur&&PG.summary&&PG.summary.current)cur=phases.find(p=>p.name===S(PG.summary.current))||null;
const prog={has:!!PG.programme,status:S(PG.programme&&PG.programme.status),phases:phases.map(p=>({id:p.id,name:p.name,start:p.start,end:p.end,pct:p.pct})),current:cur?cur.id:'',ids:[].concat.apply(phases.map(p=>p.id),phases.map(p=>p.tasks))};
